-- Staging tax catalogue, scoped client profiles and evidence-backed release checks.
ALTER TABLE erp_private.tax_rates DROP CONSTRAINT tax_rates_tax_type_check;
ALTER TABLE erp_private.tax_rates ADD CONSTRAINT tax_rates_tax_type_check CHECK(tax_type IN ('VAT','PAYE','Corporation tax','Individual income tax','Withholding tax','Levy','Turnover tax','Rental income tax','Capital gains tax','NSSF','Relief / deduction','Interest benchmark'));
ALTER TABLE erp_private.tax_rates ALTER COLUMN created_by DROP NOT NULL;
ALTER TABLE erp_private.tax_rates ADD COLUMN is_test boolean NOT NULL DEFAULT false;
ALTER TABLE erp_private.tax_rates ADD COLUMN catalog_source text;
ALTER TABLE erp_private.tax_rates ADD COLUMN source_verified_on date;
ALTER TABLE erp_private.tax_cases DROP CONSTRAINT tax_cases_kind_check;
ALTER TABLE erp_private.tax_cases ADD CONSTRAINT tax_cases_kind_check CHECK(kind IN ('VAT','PAYE','Company','Partnership','Individual','TOT','MRI','WHT','CGT','Housing levy','SHIF','NSSF','NITA','Fringe benefit','Deemed interest'));
ALTER TABLE erp_private.tax_row_reviews ADD COLUMN vat_rate_key text;
ALTER TABLE erp_private.tax_row_reviews ADD COLUMN vat_difference_reason text;
ALTER TABLE erp_private.tax_row_reviews ADD COLUMN income_treatment text CHECK(income_treatment IN ('Allowable','Disallowable','Capital','Inventory','Review'));
ALTER TABLE erp_private.firms ADD COLUMN vat_registered boolean;
ALTER TABLE erp_private.firms ADD COLUMN payment_instructions text;

CREATE TABLE erp_private.client_tax_profiles(
 profile_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),client_id uuid NOT NULL REFERENCES erp_private.clients,
 entity_type text NOT NULL CHECK(entity_type IN ('Company','Partnership','Individual','Other')),
 residency text NOT NULL CHECK(residency IN ('Resident','Non-resident')),regime text NOT NULL CHECK(regime IN ('Standard','TOT','MRI','Special')),
 obligations text[] NOT NULL,annual_turnover numeric(18,2),effective_from date NOT NULL,effective_to date NOT NULL,
 notes text NOT NULL,status text NOT NULL DEFAULT 'Draft' CHECK(status IN ('Draft','Verified')),
 created_by uuid NOT NULL REFERENCES erp_private.staff_members,verified_by uuid REFERENCES erp_private.staff_members,verified_at timestamptz,
 revision bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,
 CHECK(effective_to>=effective_from),CHECK(status<>'Verified' OR (verified_by IS NOT NULL AND verified_at IS NOT NULL))
);
CREATE INDEX client_tax_profiles_period_idx ON erp_private.client_tax_profiles(client_id,effective_from,effective_to) WHERE deleted_at IS NULL;
ALTER TABLE erp_private.client_tax_profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE erp_private.client_tax_profiles FORCE ROW LEVEL SECURITY;
GRANT SELECT,INSERT,UPDATE ON erp_private.client_tax_profiles TO erp_api;
CREATE POLICY tax_profile_read ON erp_private.client_tax_profiles FOR SELECT TO erp_api USING(erp_private.client_allowed(client_id) AND (erp_private.actor()).category_code<>'INTERN');
CREATE POLICY tax_profile_add ON erp_private.client_tax_profiles FOR INSERT TO erp_api WITH CHECK(erp_private.is_leader() AND erp_private.client_allowed(client_id) AND created_by=(erp_private.actor()).staff_id AND status='Draft');
CREATE POLICY tax_profile_update ON erp_private.client_tax_profiles FOR UPDATE TO erp_api USING(erp_private.is_leader() AND erp_private.client_allowed(client_id) AND status='Draft') WITH CHECK(erp_private.is_leader() AND erp_private.client_allowed(client_id));
CREATE TRIGGER no_delete BEFORE DELETE ON erp_private.client_tax_profiles FOR EACH ROW EXECUTE FUNCTION erp_private.reject_delete();
CREATE TRIGGER change_audit AFTER INSERT OR UPDATE ON erp_private.client_tax_profiles FOR EACH ROW EXECUTE FUNCTION erp_private.log_change('profile_id');
CREATE TRIGGER update_revision BEFORE UPDATE ON erp_private.client_tax_profiles FOR EACH ROW EXECUTE FUNCTION erp_private.touch_revision();
CREATE FUNCTION erp_private.tax_profile_guard() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
BEGIN
 IF OLD.status='Verified' THEN RAISE EXCEPTION 'Verified profiles are immutable; create a new dated profile' USING ERRCODE='23514';END IF;
 IF NEW.client_id<>OLD.client_id OR NEW.created_by<>OLD.created_by THEN RAISE EXCEPTION 'Profile identity cannot change';END IF;
 IF NEW.status='Verified' THEN
  IF NOT erp_private.is_leader() OR NEW.verified_by IS DISTINCT FROM (erp_private.actor()).staff_id THEN RAISE EXCEPTION 'Manager or Partner verification required' USING ERRCODE='42501';END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.client_id::text||':taxprofile',0));
  IF EXISTS(SELECT 1 FROM erp_private.client_tax_profiles p WHERE p.client_id=NEW.client_id AND p.profile_id<>NEW.profile_id AND p.status='Verified' AND p.deleted_at IS NULL AND p.effective_from<=NEW.effective_to AND p.effective_to>=NEW.effective_from) THEN RAISE EXCEPTION 'Verified profile periods overlap' USING ERRCODE='23514';END IF;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER profile_guard BEFORE UPDATE ON erp_private.client_tax_profiles FOR EACH ROW EXECUTE FUNCTION erp_private.tax_profile_guard();

CREATE TABLE erp_private.release_checks(
 check_code text PRIMARY KEY,title text NOT NULL,owner_position text NOT NULL,
 status text NOT NULL DEFAULT 'Not tested' CHECK(status IN ('Not tested','In progress','Passed','Blocked')),
 evidence text NOT NULL DEFAULT '',reviewed_by uuid REFERENCES erp_private.staff_members,reviewed_at timestamptz,
 revision bigint NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),
 CHECK(status<>'Passed' OR (length(evidence)>20 AND reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL))
);
ALTER TABLE erp_private.release_checks ENABLE ROW LEVEL SECURITY;
ALTER TABLE erp_private.release_checks FORCE ROW LEVEL SECURITY;
GRANT SELECT,UPDATE ON erp_private.release_checks TO erp_api;
CREATE POLICY release_read ON erp_private.release_checks FOR SELECT TO erp_api USING(erp_private.is_leader());
CREATE POLICY release_update ON erp_private.release_checks FOR UPDATE TO erp_api USING((erp_private.actor()).category_code='PARTNER') WITH CHECK((erp_private.actor()).category_code='PARTNER' AND reviewed_by=(erp_private.actor()).staff_id);
CREATE TRIGGER no_delete BEFORE DELETE ON erp_private.release_checks FOR EACH ROW EXECUTE FUNCTION erp_private.reject_delete();
CREATE TRIGGER change_audit AFTER UPDATE ON erp_private.release_checks FOR EACH ROW EXECUTE FUNCTION erp_private.log_change('check_code');
CREATE TRIGGER update_revision BEFORE UPDATE ON erp_private.release_checks FOR EACH ROW EXECUTE FUNCTION erp_private.touch_revision();
INSERT INTO erp_private.release_checks(check_code,title,owner_position) VALUES
 ('ACCESS','Staff, firm and assigned-task permission tests','Engagement Partner'),
 ('AUTH','MFA, leaked-password protection, setup links and idle logout','System Administrator'),
 ('IMPORT','Client/staff counts, duplicates and opening balances reconciled','Manager'),
 ('UPLOAD','Private Excel/PDF upload and download tested by staff','Supervisor'),
 ('RECUR','Weekly/monthly generation and escalation observed','Manager'),
 ('TAX','Applicable rates approved and sample computations signed off','Engagement Partner'),
 ('FINANCE','Invoice numbering, payments and statements reconciled','Engagement Partner'),
 ('RECOVERY','Database AND document backup restored in isolation; RPO/RTO recorded','System Administrator'),
 ('CAPACITY','Agreed concurrent staff/upload load tested','System Administrator'),
 ('OPERATIONS','Monitoring, incident contacts and support ownership confirmed','Engagement Partner'),
 ('UAT','Staff acceptance and outstanding defects agreed','Manager'),
 ('CUTOVER','Production environment, rollback and migration plan approved','Engagement Partner');
REVOKE ALL ON FUNCTION erp_private.tax_profile_guard() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION erp_private.tax_profile_guard() TO erp_api;

