INSERT INTO erp_private.tax_rates(rate_key,tax_type,label,effective_from,effective_to,parameters,source_url,source_note,catalog_source,source_verified_on) VALUES ('KE_PAYE_MONTHLY','PAYE','Monthly PAYE bands and resident personal relief','2023-07-01','2026-12-31','{"bands": [{"upper": 24000, "rate": 10}, {"upper": 32333, "rate": 25}, {"upper": 500000, "rate": 30}, {"upper": 800000, "rate": 32.5}, {"upper": null, "rate": 35}], "personal_relief": 2400, "period": "Monthly"}'::jsonb,'https://www.kra.go.ke/individual/filing-paying/types-of-taxes/paye','Income Tax Act Third Schedule. Cumulative MONTHLY upper limits. Personal relief only where residence eligibility is established.','KE-20261024','2026-10-24');
