INSERT INTO erp_private.tax_rates(rate_key,tax_type,label,effective_from,effective_to,parameters,source_url,source_note,catalog_source,source_verified_on) VALUES ('KE_NSSF','NSSF','NSSF Year 4 (February 2026 onwards)','2026-02-01','2026-12-31','{"employee_rate": 6, "employer_rate": 6, "lower_limit": 9000, "upper_limit": 108000}'::jsonb,'https://www.nssf.or.ke/notice-to-employers-year-4-2026-nssf-contribution-rates','Year 4 official notice. Per employee limits; Tier I 540 each, Tier II up to 5940 each, total maximum 6480 each. Earlier payroll periods need the earlier approved schedule.','KE-20261024','2026-10-24');
INSERT INTO erp_private.tax_rates(rate_key,tax_type,label,effective_from,effective_to,parameters,source_url,source_note,catalog_source,source_verified_on) VALUES ('KE_NITA','Levy','Employer industrial training levy','2026-01-01','2026-12-31','{"method": "fixed", "fixed_amount": 50, "basis": "Per employee per month"}'::jsonb,'https://www.nita.go.ke/our-services/levy-inspectorate.html','Industrial Training Act / Levy Order. Employer cost, not an employee deduction. Confirm any exemption. Remittance calendar must be separately verified.','KE-20261024','2026-10-24');
