CREATE FUNCTION erp_private.approved_rule_guard() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
BEGIN
 IF NEW.status='Approved' AND OLD.status<>'Approved' THEN
  IF NEW.is_test OR NEW.rate_key ~* '^QA' OR NEW.label ~* '(FICTIONAL|SYNTHETIC TEST)' THEN RAISE EXCEPTION 'Test-only rates cannot be approved' USING ERRCODE='23514';END IF;
  IF NEW.approved_by IS DISTINCT FROM (erp_private.actor()).staff_id THEN RAISE EXCEPTION 'Rate approver identity mismatch' USING ERRCODE='42501';END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.rate_key,0));
  IF EXISTS(SELECT 1 FROM erp_private.tax_rates r WHERE r.rate_key=NEW.rate_key AND r.rate_id<>NEW.rate_id AND r.status='Approved' AND r.deleted_at IS NULL AND r.effective_from<=NEW.effective_to AND r.effective_to>=NEW.effective_from) THEN RAISE EXCEPTION 'Approved rule periods overlap' USING ERRCODE='23514';END IF;
 END IF;RETURN NEW;
END;$$;
REVOKE ALL ON FUNCTION erp_private.approved_rule_guard() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION erp_private.approved_rule_guard() TO erp_api;
CREATE TRIGGER approved_rule_guard BEFORE UPDATE ON erp_private.tax_rates FOR EACH ROW EXECUTE FUNCTION erp_private.approved_rule_guard();
